#include <vector>
#include <queue>
#include <set>
#include <algorithm>
using namespace std;

class Solution {
public:
    vector<int> busiestServers(int k, vector<int>& arrival, vector<int>& load) {
        priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<>> busy;
        set<int> avail;
        for (int i = 0; i < k; ++i) avail.insert(i);
        vector<int> count(k, 0);
        int n = arrival.size();
        for (int i = 0; i < n; ++i) {
            long long t = arrival[i], l = load[i];
            while (!busy.empty() && busy.top().first <= t) {
                avail.insert(busy.top().second);
                busy.pop();
            }
            if (avail.empty()) continue;
            auto it = avail.lower_bound(i % k);
            if (it == avail.end()) it = avail.begin();
            int server = *it;
            avail.erase(it);
            count[server]++;
            busy.push({t + l, server});
        }
        int max_c = *max_element(count.begin(), count.end());
        vector<int> res;
        for (int i = 0; i < k; ++i) {
            if (count[i] == max_c) res.push_back(i);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public List<Integer> busiestServers(int k, int[] arrival, int[] load) {
        PriorityQueue<int[]> busy = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        TreeSet<Integer> avail = new TreeSet<>();
        for (int i = 0; i < k; ++i) avail.add(i);
        int[] count = new int[k];
        int n = arrival.length;
        for (int i = 0; i < n; ++i) {
            int t = arrival[i], l = load[i];
            while (!busy.isEmpty() && busy.peek()[0] <= t) {
                avail.add(busy.poll()[1]);
            }
            if (avail.isEmpty()) continue;
            Integer server = avail.ceiling(i % k);
            if (server == null) server = avail.first();
            avail.remove(server);
            count[server]++;
            busy.offer(new int[]{t + l, server});
        }
        int maxC = 0;
        for (int c : count) maxC = Math.max(maxC, c);
        List<Integer> res = new ArrayList<>();
        for (int i = 0; i < k; ++i) {
            if (count[i] == maxC) res.add(i);
        }
        return res;
    }
}

/**
 * @param {number} k
 * @param {number[]} arrival
 * @param {number[]} load
 * @return {number[]}
 */
var busiestServers = function(k, arrival, load) {
    const busy = []; // min-heap simulation
    const avail = Array.from({ length: k }, (_, i) => i);
    const count = Array(k).fill(0);
    const n = arrival.length;

    for (let i = 0; i < n; ++i) {
        const t = arrival[i], l = load[i];
        while (busy.length > 0 && busy[0][0] <= t) {
            busy.sort((a, b) => a[0] - b[0]);
            if (busy[0][0] > t) break;
            const [, s] = busy.shift();
            // insert s in sorted order into avail
            let lo = 0, hi = avail.length;
            while (lo < hi) {
                const mid = (lo + hi) >> 1;
                if (avail[mid] < s) lo = mid + 1;
                else hi = mid;
            }
            avail.splice(lo, 0, s);
        }
        if (avail.length === 0) continue;
        const target = i % k;
        let lo = 0, hi = avail.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (avail[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        if (lo === avail.length) lo = 0;
        const server = avail.splice(lo, 1)[0];
        count[server]++;
        busy.push([t + l, server]);
        busy.sort((a, b) => a[0] - b[0]);
    }
    const maxC = Math.max(...count);
    const res = [];
    for (let i = 0; i < k; ++i) {
        if (count[i] === maxC) res.push(i);
    }
    return res;
};
